//! 🔺️ Mesh primitives and indexed, ordered numeric buffers with explicit material relationships.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use super::{SemioMeshSnapshot,SemioMesh,SemioPrimitive,SemioTopology,SemioMaterial,SemioTexture,SemioPoint3,SemioUv,SemioRgba};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,reconstruct_text,reconstruct_blob},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase}};
use std::collections::{BTreeMap,BTreeSet};
fn number(value:usize)->Result<i64,String>{i64::try_from(value).map_err(|error|error.to_string())}
fn identity<'a>(row:impl std::borrow::Borrow<SqliteRow<'a>>,columns:usize)->Result<(),String>{let row=*row.borrow();if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=columns{Err("invalid Semio mesh row identity or columns".into())}else{Ok(())}}
fn tick(control:&mut SqliteSnapshotControl<'_>,completed:&mut usize)->Result<(),String>{*completed+=1;if *completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*completed,0)?;}Ok(())}
fn ordered<'a>(mut rows:Vec<SqliteRow<'a>>)->Result<Vec<SqliteRow<'a>>,String>{rows.sort_by_key(|row|row.integer(2).unwrap_or(-1));for(ordinal,row)in rows.iter().enumerate(){if row.integer(2)?!=number(ordinal)?{return Err("Semio mesh ordinals must be contiguous".into());}}Ok(rows)}
fn relationships<'a>(db:&'a SqliteDatabase,table:&str,columns:usize,owners:&BTreeSet<i64>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<SqliteRow<'a>>>,String>{let mut result=BTreeMap::new();let mut ids=BTreeSet::new();for(count,row)in float_rows(db,table,control)?.into_iter().enumerate(){identity(row,columns)?;if !owners.contains(&row.integer(1)?)||!ids.insert(row.rowid){return Err("invalid Semio mesh relationship owner or identity".into());}row.integer(2)?;result.entry(row.integer(1)?).or_insert_with(Vec::new).push(row);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn topology(value:SemioTopology)->&'static str{match value{SemioTopology::Points=>"points",SemioTopology::Lines=>"lines",SemioTopology::LineStrip=>"line_strip",SemioTopology::Triangles=>"triangles",SemioTopology::TriangleStrip=>"triangle_strip",SemioTopology::TriangleFan=>"triangle_fan"}}
impl ArtifactSqliteSnapshot for SemioMeshSnapshot{
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="mesh"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_mesh_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key_float("semio_mesh_document",1,&[Cell::Text(&self.schema)])?;let mut materials=BTreeMap::new();for(ordinal,material)in self.materials.iter().enumerate(){let c=material.base_color;let id=p.insert_float("semio_mesh_material",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&material.id),Cell::Float32(c.r),Cell::Float32(c.g),Cell::Float32(c.b),Cell::Float32(c.a),Cell::Float32(material.metallic),Cell::Float32(material.roughness)])?;if materials.insert(material.id.as_str(),id).is_some(){return Err("duplicate Semio mesh material identifier".into());}}
let mut meshes=BTreeSet::new();for(ordinal,mesh)in self.meshes.iter().enumerate(){let mesh_id=p.insert_float("semio_mesh_mesh",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&mesh.id)])?;if !meshes.insert(mesh.id.as_str()){return Err("duplicate Semio mesh identifier".into());}let mut primitive_ids=BTreeSet::new();for(ordinal,primitive)in mesh.primitives.iter().enumerate(){if !primitive_ids.insert(primitive.id.as_str()){return Err("duplicate Semio mesh primitive identifier".into());}let material=match &primitive.material_id{None=>Cell::Null,Some(id)=>Cell::Integer(*materials.get(id.as_str()).ok_or("dangling Semio mesh primitive material")?)};let id=p.insert_float("semio_mesh_primitive",&[Cell::Integer(mesh_id),Cell::Integer(number(ordinal)?),Cell::Text(&primitive.id),Cell::Text(topology(primitive.topology)),material])?;let mut first_position=0;
for(ordinal,position)in primitive.positions.iter().enumerate(){let row=p.insert_float("semio_mesh_position",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(position.x),Cell::Real(position.y),Cell::Real(position.z)])?;if ordinal==0{first_position=row;}}
for(ordinal,normal)in primitive.normals.iter().enumerate(){p.insert_float("semio_mesh_normal",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(normal.x),Cell::Real(normal.y),Cell::Real(normal.z)])?;}
for(ordinal,uv)in primitive.uvs.iter().enumerate(){p.insert_float("semio_mesh_uv",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(uv.u),Cell::Real(uv.v)])?;}
for(ordinal,color)in primitive.colors.iter().enumerate(){p.insert_float("semio_mesh_color",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Float32(color.r),Cell::Float32(color.g),Cell::Float32(color.b),Cell::Float32(color.a)])?;}
for(ordinal,index)in primitive.indices.iter().enumerate(){if usize::try_from(*index).map_err(|error|error.to_string())?>=primitive.positions.len(){return Err("Semio mesh vertex index is out of bounds".into());}p.insert_float("semio_mesh_index",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(i64::from(*index)),Cell::Integer(first_position.checked_add(i64::from(*index)).ok_or("Semio mesh position identifier overflow")?)])?;}}}
let mut textures=BTreeSet::new();for(ordinal,texture)in self.textures.iter().enumerate(){if !textures.insert(texture.id.as_str()){return Err("duplicate Semio mesh texture identifier".into());}p.insert_float("semio_mesh_texture",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&texture.id),Cell::Text(&texture.mime),Cell::Blob(&texture.bytes)])?;}p.finish()
}
fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(database, control, Self::SQLITE_SCHEMA) }
}

impl SemioMeshSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {

control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,declared_schema,control.limits()).map_err(|error|error.to_string())?;let document=single_float_row(database,"semio_mesh_document")?;identity(document,2)?;if document.rowid!=1{return Err("invalid Semio mesh document identifier".into());}let mut completed=0usize;
let mut materials=Vec::new();let mut material_names=BTreeMap::new();let mut ids=BTreeSet::new();for row in ordered_float_rows(database,"semio_mesh_material",2,control)?{identity(row,10)?;if row.integer(1)?!=1||material_names.insert(row.rowid,row.text(3)?).is_some()||!ids.insert(row.text(3)?){return Err("invalid Semio mesh material owner or identity".into());}materials.push(SemioMaterial{id:reconstruct_text(control,row.text(3)?)?,base_color:SemioRgba{r:row.binary32(4)?,g:row.binary32(5)?,b:row.binary32(6)?,a:row.binary32(7)?},metallic:row.binary32(8)?,roughness:row.binary32(9)?});tick(control,&mut completed)?;}
let mesh_rows=ordered_float_rows(database,"semio_mesh_mesh",2,control)?;let mut mesh_ids=BTreeSet::new();let mut names=BTreeSet::new();for row in &mesh_rows{identity(row,4)?;if row.integer(1)?!=1||!mesh_ids.insert(row.rowid)||!names.insert(row.text(3)?){return Err("invalid Semio mesh owner or identity".into());}}
let mut primitives=relationships(database,"semio_mesh_primitive",6,&mesh_ids,control)?;let primitive_ids=primitives.values().flatten().map(|row|row.rowid).collect::<BTreeSet<_>>();let mut positions=relationships(database,"semio_mesh_position",6,&primitive_ids,control)?;let mut normals=relationships(database,"semio_mesh_normal",6,&primitive_ids,control)?;let mut uvs=relationships(database,"semio_mesh_uv",5,&primitive_ids,control)?;let mut colors=relationships(database,"semio_mesh_color",7,&primitive_ids,control)?;let mut indices=relationships(database,"semio_mesh_index",5,&primitive_ids,control)?;let position_refs=positions.values().flatten().map(|row|Ok((row.rowid,(row.integer(1)?,row.integer(2)?)))).collect::<Result<BTreeMap<_,_>,String>>()?;
let mut meshes=Vec::new();for mesh in mesh_rows{let mut native_primitives=Vec::new();let mut ids=BTreeSet::new();for primitive in ordered(primitives.remove(&mesh.rowid).unwrap_or_default())?{if !ids.insert(primitive.text(3)?){return Err("duplicate Semio mesh primitive native identifier".into());}let topology=match primitive.text(4)?{"points"=>SemioTopology::Points,"lines"=>SemioTopology::Lines,"line_strip"=>SemioTopology::LineStrip,"triangles"=>SemioTopology::Triangles,"triangle_strip"=>SemioTopology::TriangleStrip,"triangle_fan"=>SemioTopology::TriangleFan,_=>return Err("unknown Semio mesh topology".into())};let material_id=if primitive.is_null(5)?{None}else{Some(reconstruct_text(control,material_names.get(&primitive.integer(5)?).ok_or("dangling Semio mesh primitive material")?)?)};let mut native_positions=Vec::new();for row in ordered(positions.remove(&primitive.rowid).unwrap_or_default())?{native_positions.push(SemioPoint3{x:row.real(3)?,y:row.real(4)?,z:row.real(5)?});tick(control,&mut completed)?;}let mut native_normals=Vec::new();for row in ordered(normals.remove(&primitive.rowid).unwrap_or_default())?{native_normals.push(SemioPoint3{x:row.real(3)?,y:row.real(4)?,z:row.real(5)?});tick(control,&mut completed)?;}let mut native_uvs=Vec::new();for row in ordered(uvs.remove(&primitive.rowid).unwrap_or_default())?{native_uvs.push(SemioUv{u:row.real(3)?,v:row.real(4)?});tick(control,&mut completed)?;}let mut native_colors=Vec::new();for row in ordered(colors.remove(&primitive.rowid).unwrap_or_default())?{native_colors.push(SemioRgba{r:row.binary32(3)?,g:row.binary32(4)?,b:row.binary32(5)?,a:row.binary32(6)?});tick(control,&mut completed)?;}let mut native_indices=Vec::new();for row in ordered(indices.remove(&primitive.rowid).unwrap_or_default())?{let index=u32::try_from(row.integer(3)?).map_err(|error|error.to_string())?;let position=position_refs.get(&row.integer(4)?).ok_or("dangling Semio mesh indexed position")?;if position.0!=primitive.rowid||position.1!=i64::from(index){return Err("Semio mesh vertex index disagrees with position relationship".into());}native_indices.push(index);tick(control,&mut completed)?;}native_primitives.push(SemioPrimitive{id:reconstruct_text(control,primitive.text(3)?)?,topology,positions:native_positions,normals:native_normals,uvs:native_uvs,colors:native_colors,indices:native_indices,material_id});}meshes.push(SemioMesh{id:reconstruct_text(control,mesh.text(3)?)?,primitives:native_primitives});}
let mut textures=Vec::new();let mut ids=BTreeSet::new();let mut names=BTreeSet::new();for row in ordered_float_rows(database,"semio_mesh_texture",2,control)?{identity(row,6)?;if row.integer(1)?!=1||!ids.insert(row.rowid)||!names.insert(row.text(3)?){return Err("invalid Semio mesh texture owner or identity".into());}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;textures.push(SemioTexture{id:reconstruct_text(control,row.text(3)?)?,mime:reconstruct_text(control,row.text(4)?)?,bytes:reconstruct_blob(control,row.blob(5)?)?});tick(control,&mut completed)?;}
control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,completed)?;Ok(Self{schema:reconstruct_text(control,document.text(1)?)?,meshes,materials,textures})
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_mesh_position"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)],"semio_mesh_normal"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)],"semio_mesh_uv"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_mesh_color"=>&[FloatColumn::Binary32(3),FloatColumn::Binary32(4),FloatColumn::Binary32(5),FloatColumn::Binary32(6)],"semio_mesh_material"=>&[FloatColumn::Binary32(4),FloatColumn::Binary32(5),FloatColumn::Binary32(6),FloatColumn::Binary32(7),FloatColumn::Binary32(8),FloatColumn::Binary32(9)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=Vec::new();for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let mut result=Vec::new();for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,String>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioMeshSnapshot{
/// 📏️ Bounds explicitly owned native fields before encoding.
pub fn native_fields(&self,b:&mut Bound<'_,'_>)->Result<(),String>{b.text(&self.schema)?;b.entities(self.meshes.len())?;for mesh in &self.meshes{b.text(&mesh.id)?;b.entities(mesh.primitives.len())?;for primitive in &mesh.primitives{b.text(&primitive.id)?;b.optional_text(primitive.material_id.as_deref())?;b.scalars(1)?;for(count,width)in[(primitive.positions.len(),3),(primitive.normals.len(),3),(primitive.uvs.len(),2),(primitive.colors.len(),4),(primitive.indices.len(),1)]{b.entities(count)?;b.scalars(count.checked_mul(width).ok_or("Semio mesh native scalar count overflow")?)?;}}}b.entities(self.materials.len())?;for material in &self.materials{b.text(&material.id)?;b.scalars(6)?;}b.entities(self.textures.len())?;for texture in &self.textures{b.text(&texture.id)?;b.text(&texture.mime)?;b.bytes(&texture.bytes)?;}Ok(())}
}
